@page "/settings"
@using sv_7ed63c763c5d4bf38b7dae42922a97cf.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")" @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span>@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @_toastType">@_toastMessage</div>
        }
    </main>
</div>

@* ===== Profile Section ===== *@
@{
    RenderFragment RenderProfileSection() => @<section class="settings-section">
        <h2>Profile</h2>
        <div class="profile-layout">
            <div class="avatar-area">
                <img src="@_profileDisplayName" alt="Avatar" class="avatar-preview" style="display:none;" />
                <div class="avatar-placeholder">
                    <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-preview" />
                </div>
                <p class="avatar-url-display">@_profileAvatarUrl</p>
            </div>
            <div class="profile-fields">
                <div class="form-group">
                    <label for="displayName">Display Name</label>
                    <input id="displayName" type="text" @bind="_profileDisplayName" />
                </div>
                <div class="form-group">
                    <label for="email">Email</label>
                    <input id="email" type="email" @bind="_profileEmail" />
                </div>
                <div class="form-group">
                    <label for="bio">Bio</label>
                    <textarea id="bio" rows="4" @bind="_profileBio"></textarea>
                </div>
                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                    <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                </div>
            </div>
        </div>
    </section>;
}

@* ===== Notifications Section ===== *@
@{
    RenderFragment RenderNotificationsSection() => @<section class="settings-section">
        <h2>Notifications</h2>
        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_emailNotifications" />
                <span class="toggle-switch"></span>
                <span>Email Notifications</span>
            </label>
            <label class="toggle-label">
                <input type="checkbox" @bind="_pushNotifications" />
                <span class="toggle-switch"></span>
                <span>Push Notifications</span>
            </label>
            <label class="toggle-label">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span class="toggle-switch"></span>
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @if (_allChannels != null)
            {
                @foreach (var channel in _allChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox" checked="@IsChannelMuted(ch)" @onchange="(e) => ToggleChannelMute(ch, (bool)(e.Value ?? false))" />
                        <span>#@ch</span>
                    </label>
                }
            }
        </div>
        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    </section>;
}

@* ===== Security Section ===== *@
@{
    RenderFragment RenderSecuritySection() => @<section class="settings-section">
        <h2>Security</h2>

        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(_passwordPanelOpen ? "▾" : "▸")</span>
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="security-item">
            <div class="security-info">
                <h3>Two-Factor Authentication</h3>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <label class="toggle-label">
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span class="toggle-switch"></span>
            </label>
        </div>

        @if (_lastPasswordChange.HasValue)
        {
            <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <h3>Active Sessions</h3>
        <div class="sessions-table-wrapper">
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @if (_sessions != null)
                    {
                        @foreach (var session in _sessions)
                        {
                            var s = session;
                            <tr>
                                <td>@s.Device</td>
                                <td>@s.Location</td>
                                <td>@FormatLastActive(s.LastActive)</td>
                                <td>
                                    @if (s.Id != _currentSessionId)
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(s.Id)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>
        </div>

        @if (_showRevokeConfirmation)
        {
            <div class="modal-overlay">
                <div class="modal">
                    <h3>Revoke Session</h3>
                    <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                        <button class="btn btn-secondary" @onclick="() => _showRevokeConfirmation = false">Cancel</button>
                    </div>
                </div>
            </div>
        }
    </section>;
}

@* ===== Appearance Section ===== *@
@{
    RenderFragment RenderAppearanceSection() => @<section class="settings-section">
        <h2>Appearance</h2>

        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label class="radio-label">
                    <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange='() => _theme = "Light"' />
                    <span>Light</span>
                </label>
                <label class="radio-label">
                    <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange='() => _theme = "Dark"' />
                    <span>Dark</span>
                </label>
                <label class="radio-label">
                    <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange='() => _theme = "System"' />
                    <span>System</span>
                </label>
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange='() => _fontSize = "Small"' />
                    <span>Small</span>
                </label>
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange='() => _fontSize = "Medium"' />
                    <span>Medium</span>
                </label>
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange='() => _fontSize = "Large"' />
                    <span>Large</span>
                </label>
            </div>
        </div>

        <div class="form-group">
            <label for="language">Language</label>
            <select id="language" @bind="_language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
            </select>
        </div>

        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_compactMode" />
                <span class="toggle-switch"></span>
                <span>Compact Mode</span>
            </label>
        </div>

        <h3>Live Preview</h3>
        <div class="preview-area @GetPreviewClasses()">
            <div class="preview-card">
                <h4>Preview Card</h4>
                <p>This is how your content will look with the selected settings.</p>
                <button class="btn btn-primary">Sample Button</button>
            </div>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    </section>;
}

@code {
    private record SectionInfo(string Label, string Icon);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨")
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;
    private string? _toastMessage;
    private string _toastType = "success";

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = new();
    private List<string> _allChannels = new();

    // Security state
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession>? _sessions;
    private string _currentSessionId = "session-1";
    private bool _showRevokeConfirmation;
    private string? _sessionToRevoke;

    // Appearance state
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = notifs.EmailNotifications;
        _pushNotifications = notifs.PushNotifications;
        _weeklyDigest = notifs.WeeklyDigest;
        _allChannels = new List<string>(notifs.MutedChannels);
        _mutedChannels = new List<string>(notifs.MutedChannels);

        var security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = security.TwoFactorEnabled;
        _lastPasswordChange = security.LastPasswordChange;
        _sessions = security.Sessions;

        var appearance = await SettingsService.GetAppearanceAsync();
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile != null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // Notifications actions
    private bool IsChannelMuted(string channel) => _mutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", "error");
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _lastPasswordChange = DateTime.UtcNow;
        _passwordPanelOpen = false;
        await ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevoke(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _sessions = _sessions?.Where(s => s.Id != _sessionToRevoke).ToList();
            _sessionToRevoke = null;
            _showRevokeConfirmation = false;
            await ShowToast("Session revoked.", "success");
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }

    // Appearance actions
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private async Task ShowToast(string message, string type)
    {
        _toastMessage = message;
        _toastType = type;
        StateHasChanged();
        await Task.Delay(3000);
        _toastMessage = null;
        StateHasChanged();
    }
}

