                </div>
            }
        </div>

        <div class="security-item">
            <div class="security-info">
                <h3>Two-Factor Authentication</h3>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <label class="toggle-label">
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span class="toggle-switch"></span>
            </label>
        </div>

        @if (_lastPasswordChange.HasValue)
        {
            <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <h3>Active Sessions</h3>
        <div class="sessions-table-wrapper">
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @if (_sessions != null)
                    {
                        @foreach (var session in _sessions)
                        {
                            var s = session;
                            <tr>
                                <td>@s.Device</td>
                                <td>@s.Location</td>
                                <td>@FormatLastActive(s.LastActive)</td>
                                <td>
                                    @if (s.Id != _currentSessionId)
                                    {
                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(s.Id)">Revoke</button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    }
                </tbody>
            </table>
        </div>

        @if (_showRevokeConfirmation)
        {
            <div class="modal-overlay">
                <div class="modal">
                    <h3>Revoke Session</h3>
                    <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                        <button class="btn btn-secondary" @onclick="() => _showRevokeConfirmation = false">Cancel</button>
                    </div>
                </div>
            </div>
        }
    </section>;
}

