+
+    // Notifications actions
+    private bool IsChannelMuted(string channel) => _mutedChannels.Contains(channel);
+
+    private void ToggleChannelMute(string channel, bool muted)
+    {
+        if (muted && !_mutedChannels.Contains(channel))
+            _mutedChannels.Add(channel);
+        else if (!muted)
+            _mutedChannels.Remove(channel);
+    }
+
+    private async Task SaveNotifications()
+    {
+        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        await ShowToast("Notification preferences saved!", "success");
+    }
+
+    // Security actions
+    private async Task UpdatePassword()
+    {
+        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
+        {
+            await ShowToast("Please fill in all password fields.", "error");
+            return;
+        }
+
+        if (_newPassword != _confirmPassword)
+        {
+            await ShowToast("New passwords do not match.", "error");
+            return;
+        }
+
+        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+        _currentPassword = "";
+        _newPassword = "";
+        _confirmPassword = "";
+        _lastPasswordChange = DateTime.UtcNow;
+        _passwordPanelOpen = false;
+        await ShowToast("Password updated successfully!", "success");
+    }
+
+    private void ConfirmRevoke(string sessionId)
+    {
+        _sessionToRevoke = sessionId;
+        _showRevokeConfirmation = true;
+    }
+
+    private async Task RevokeSession()
+    {
+        if (_sessionToRevoke != null)
+        {
+            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
+            _sessions = _sessions?.Where(s => s.Id != _sessionToRevoke).ToList();
+            _sessionToRevoke = null;
+            _showRevokeConfirmation = false;
+            await ShowToast("Session revoked.", "success");
+        }
+    }
+
+    private static string FormatLastActive(DateTime lastActive)
+    {
+        var diff = DateTime.UtcNow - lastActive;
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
+        return $"{(int)diff.TotalDays} days ago";
+    }
+
+    // Appearance actions
+    private string GetPreviewClasses()
+    {
+        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
+        if (_compactMode) classes += " preview-compact";
+        return classes;
+    }
+
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
