+    }
+
+    // Toast
+    private async Task ShowToast(string message, string type)
+    {
+        _toastMessage = message;
+        _toastType = type;
+        StateHasChanged();
+        await Task.Delay(3000);
+        _toastMessage = null;
+        StateHasChanged();
+    }
+}
