+        }
+
+        <h3>Active Sessions</h3>
+        <div class="sessions-table-wrapper">
+            <table class="sessions-table">
+                <thead>
+                    <tr>
+                        <th>Device</th>
+                        <th>Location</th>
+                        <th>Last Active</th>
+                        <th></th>
+                    </tr>
+                </thead>
+                <tbody>
+                    @if (_sessions != null)
+                    {
+                        @foreach (var session in _sessions)
+                        {
+                            var s = session;
+                            <tr>
+                                <td>@s.Device</td>
+                                <td>@s.Location</td>
+                                <td>@FormatLastActive(s.LastActive)</td>
+                                <td>
+                                    @if (s.Id != _currentSessionId)
+                                    {
+                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(s.Id)">Revoke</button>
+                                    }
+                                    else
+                                    {
+                                        <span class="current-badge">Current</span>
+                                    }
+                                </td>
+                            </tr>
+                        }
+                    }
+                </tbody>
+            </table>
+        </div>
+
+        @if (_showRevokeConfirmation)
+        {
+            <div class="modal-overlay">
+                <div class="modal">
+                    <h3>Revoke Session</h3>
+                    <p>Are you sure you want to revoke this session? The device will be signed out immediately.</p>
+                    <div class="button-group">
+                        <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
+                        <button class="btn btn-secondary" @onclick="() => _showRevokeConfirmation = false">Cancel</button>
+                    </div>
+                </div>
+            </div>
+        }
+    </section>;
+}
+
+@* ===== Appearance Section ===== *@
+@{
+    RenderFragment RenderAppearanceSection() => @<section class="settings-section">
+        <h2>Appearance</h2>
+
+        <div class="form-group">
+            <label>Theme</label>
+            <div class="radio-group">
+                <label class="radio-label">
+                    <input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange='() => _theme = "Light"' />
+                    <span>Light</span>
+                </label>
+                <label class="radio-label">
+                    <input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange='() => _theme = "Dark"' />
+                    <span>Dark</span>
+                </label>
+                <label class="radio-label">
+                    <input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange='() => _theme = "System"' />
+                    <span>System</span>
+                </label>
+            </div>
+        </div>
+
+        <div class="form-group">
+            <label>Font Size</label>
+            <div class="radio-group">
+                <label class="radio-label">
+                    <input type="radio" name="fontSize" value="Small" checked="@(_fontSize == "Small")" @onchange='() => _fontSize = "Small"' />
+                    <span>Small</span>
+                </label>
+                <label class="radio-label">
+                    <input type="radio" name="fontSize" value="Medium" checked="@(_fontSize == "Medium")" @onchange='() => _fontSize = "Medium"' />
+                    <span>Medium</span>
+                </label>
+                <label class="radio-label">
+                    <input type="radio" name="fontSize" value="Large" checked="@(_fontSize == "Large")" @onchange='() => _fontSize = "Large"' />
+                    <span>Large</span>
+                </label>
+            </div>
+        </div>
+
+        <div class="form-group">
+            <label for="language">Language</label>
+            <select id="language" @bind="_language">
+                <option value="English">English</option>
+                <option value="Spanish">Spanish</option>
+                <option value="French">French</option>
+                <option value="German">German</option>
+                <option value="Japanese">Japanese</option>
+                <option value="Chinese">Chinese</option>
+            </select>
+        </div>
+
+        <div class="toggle-group">
+            <label class="toggle-label">
+                <input type="checkbox" @bind="_compactMode" />
+                <span class="toggle-switch"></span>
+                <span>Compact Mode</span>
+            </label>
+        </div>
+
+        <h3>Live Preview</h3>
+        <div class="preview-area @GetPreviewClasses()">
+            <div class="preview-card">
+                <h4>Preview Card</h4>
+                <p>This is how your content will look with the selected settings.</p>
+                <button class="btn btn-primary">Sample Button</button>
+            </div>
+        </div>
+
+        <div class="button-group">
+            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
+        </div>
+    </section>;
+}
+
+@code {
+    private record SectionInfo(string Label, string Icon);
+
+    private readonly Dictionary<string, SectionInfo> _sections = new()
+    {
+        ["profile"] = new("Profile", "👤"),
+        ["notifications"] = new("Notifications", "🔔"),
+        ["security"] = new("Security", "🔒"),
+        ["appearance"] = new("Appearance", "🎨")
+    };
+
+    private string ActiveSection { get; set; } = "profile";
+    private bool _loading = true;
+    private string? _toastMessage;
+    private string _toastType = "success";
+
+    // Profile state
+    private string _profileDisplayName = "";
+    private string _profileEmail = "";
+    private string _profileAvatarUrl = "";
+    private string _profileBio = "";
+    private UserProfile? _savedProfile;
+
+    // Notifications state
+    private bool _emailNotifications;
+    private bool _pushNotifications;
+    private bool _weeklyDigest;
+    private List<string> _mutedChannels = new();
+    private List<string> _allChannels = new();
+
+    // Security state
+    private bool _passwordPanelOpen;
+    private string _currentPassword = "";
+    private string _newPassword = "";
+    private string _confirmPassword = "";
+    private bool _twoFactorEnabled;
+    private DateTime? _lastPasswordChange;
+    private List<ActiveSession>? _sessions;
+    private string _currentSessionId = "session-1";
+    private bool _showRevokeConfirmation;
+    private string? _sessionToRevoke;
+
+    // Appearance state
+    private string _theme = "Light";
+    private string _fontSize = "Medium";
+    private string _language = "English";
+    private bool _compactMode;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAllSettings();
+        _loading = false;
+    }
+
+    private async Task LoadAllSettings()
+    {
+        var profile = await SettingsService.GetProfileAsync();
+        _savedProfile = profile;
+        ApplyProfile(profile);
+
+        var notifs = await SettingsService.GetNotificationPrefsAsync();
+        _emailNotifications = notifs.EmailNotifications;
+        _pushNotifications = notifs.PushNotifications;
+        _weeklyDigest = notifs.WeeklyDigest;
+        _allChannels = new List<string>(notifs.MutedChannels);
+        _mutedChannels = new List<string>(notifs.MutedChannels);
+
+        var security = await SettingsService.GetSecuritySettingsAsync();
+        _twoFactorEnabled = security.TwoFactorEnabled;
+        _lastPasswordChange = security.LastPasswordChange;
+        _sessions = security.Sessions;
+
+        var appearance = await SettingsService.GetAppearanceAsync();
+        _theme = appearance.Theme;
+        _fontSize = appearance.FontSize;
+        _language = appearance.Language;
+        _compactMode = appearance.CompactMode;
+    }
+
+    private void ApplyProfile(UserProfile profile)
+    {
+        _profileDisplayName = profile.DisplayName;
+        _profileEmail = profile.Email;
+        _profileAvatarUrl = profile.AvatarUrl;
+        _profileBio = profile.Bio;
+    }
+
+    // Profile actions
+    private async Task SaveProfile()
+    {
+        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
+        await SettingsService.SaveProfileAsync(profile);
+        _savedProfile = profile;
+        await ShowToast("Profile saved successfully!", "success");
+    }
+
+    private void DiscardProfileChanges()
+    {
+        if (_savedProfile != null)
+        {
+            ApplyProfile(_savedProfile);
+        }
+    }
+
+    // Notifications actions
+    private bool IsChannelMuted(string channel) => _mutedChannels.Contains(channel);
+
+    private void ToggleChannelMute(string channel, bool muted)
+    {
+        if (muted && !_mutedChannels.Contains(channel))
+            _mutedChannels.Add(channel);
+        else if (!muted)
+            _mutedChannels.Remove(channel);
+    }
+
+    private async Task SaveNotifications()
+    {
+        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        await ShowToast("Notification preferences saved!", "success");
+    }
+
+    // Security actions
+    private async Task UpdatePassword()
+    {
+        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
+        {
+            await ShowToast("Please fill in all password fields.", "error");
+            return;
+        }
+
+        if (_newPassword != _confirmPassword)
+        {
+            await ShowToast("New passwords do not match.", "error");
+            return;
+        }
+
+        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+        _currentPassword = "";
+        _newPassword = "";
+        _confirmPassword = "";
+        _lastPasswordChange = DateTime.UtcNow;
+        _passwordPanelOpen = false;
+        await ShowToast("Password updated successfully!", "success");
+    }
+
+    private void ConfirmRevoke(string sessionId)
+    {
+        _sessionToRevoke = sessionId;
+        _showRevokeConfirmation = true;
+    }
+
+    private async Task RevokeSession()
+    {
+        if (_sessionToRevoke != null)
+        {
+            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
+            _sessions = _sessions?.Where(s => s.Id != _sessionToRevoke).ToList();
+            _sessionToRevoke = null;
+            _showRevokeConfirmation = false;
+            await ShowToast("Session revoked.", "success");
+        }
+    }
+
+    private static string FormatLastActive(DateTime lastActive)
+    {
+        var diff = DateTime.UtcNow - lastActive;
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
+        return $"{(int)diff.TotalDays} days ago";
+    }
+
+    // Appearance actions
+    private string GetPreviewClasses()
+    {
+        var classes = $"preview-theme-{_theme.ToLowerInvariant()} preview-font-{_fontSize.ToLowerInvariant()}";
+        if (_compactMode) classes += " preview-compact";
+        return classes;
+    }
+
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+        await SettingsService.SaveAppearanceAsync(settings);
+        await ShowToast("Appearance settings saved!", "success");
+    }
+
+    // Toast
+    private async Task ShowToast(string message, string type)
+    {
+        _toastMessage = message;
+        _toastType = type;
+        StateHasChanged();
+        await Task.Delay(3000);
+        _toastMessage = null;
+        StateHasChanged();
+    }
+}
+

arguments.file_text:
.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 0;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    transition: background 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    color: #1565c0;
    border-left-color: #1565c0;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    position: relative;
    overflow-y: auto;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #444;
}

/* Loading */
.loading {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 200px;
    font-size: 1.1rem;
    color: #888;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #555;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1565c0;
    box-shadow: 0 0 0 2px rgba(21, 101, 192, 0.1);
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background 0.15s, transform 0.1s;
}

.btn:active {
    transform: scale(0.97);
}

.btn-primary {
    background: #1565c0;
    color: #fff;
}

.btn-primary:hover {
    background: #1254a1;
}

.btn-secondary {
    background: #e0e0e0;
    color: #333;
}

.btn-secondary:hover {
    background: #d0d0d0;
}

.btn-danger {
    background: #d32f2f;
    color: #fff;
}

.btn-danger:hover {
    background: #b71c1c;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Profile */
.profile-layout {
    display: flex;
    gap: 2rem;
}

.avatar-area {
    text-align: center;
}

.avatar-preview {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
}

.avatar-url-display {
    font-size: 0.75rem;
    color: #888;
    max-width: 140px;
    word-break: break-all;
    margin-top: 0.5rem;
}

.profile-fields {
    flex: 1;
}

/* Toggle switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1565c0;
}

/* Channel list */
.channel-list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem 1.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item input[type="checkbox"] {
    accent-color: #1565c0;
}

/* Security */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 1rem;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.security-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.security-info {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.security-info h3 {
    margin: 0;
}

.status-indicator {
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 500;
}

.status-indicator.enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-indicator.disabled {
    background: #fce4ec;
    color: #c62828;
}

.info-text {
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    text-align: left;
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #555;
}

.current-badge {
    font-size: 0.8rem;
    background: #e3f2fd;
    color: #1565c0;
    padding: 0.2rem 0.5rem;
    border-radius: 10px;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal {
    background: #fff;
    padding: 1.5rem 2rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.modal h3 {
    margin-top: 0;
}

/* Appearance */
.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.radio-label input[type="radio"] {
    accent-color: #1565c0;
}

/* Preview area */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 0.5rem;
    transition: all 0.2s;
}

.preview-card h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

.preview-card p {
    margin-bottom: 1rem;
}

/* Preview theme variants */
.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
}

.preview-theme-dark .btn-primary {
    background: #42a5f5;
}

.preview-theme-system {
    background: #f5f5f5;
    color: #333;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card h4 {
    margin-bottom: 0.25rem;
}

.preview-compact .preview-card p {
    margin-bottom: 0.5rem;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    color: #fff;
    z-index: 2000;
    animation: slideIn 0.3s ease;
    box-shadow: 0 3px 12px rgba(0, 0, 0, 0.15);
}

.toast.success {
    background: #2e7d32;
}

.toast.error {
    background: #d32f2f;
}

@@keyframes slideIn {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* Responsive */
@@media (max-width: 768px) {
    .settings-container {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        border-right: none;
        border-bottom: 1px solid #e0e0e0;
    }

    .settings-sidebar ul {
        display: flex;
        overflow-x: auto;
    }

    .settings-sidebar li {
        border-left: none;
        border-bottom: 3px solid transparent;
        white-space: nowrap;
    }

    .settings-sidebar li.active {
        border-left-color: transparent;
        border-bottom-color: #1565c0;
    }

    .profile-layout {
        flex-direction: column;
    }
