.avatar-url-display {
    font-size: 0.75rem;
    color: #888;
    max-width: 140px;
    word-break: break-all;
    margin-top: 0.5rem;
}

.profile-fields {
    flex: 1;
}

/* Toggle switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1565c0;
}

