.channel-list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem 1.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item input[type="checkbox"] {
    accent-color: #1565c0;
}

