.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 1rem;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.security-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.security-info {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.security-info h3 {
    margin: 0;
}

.status-indicator {
