.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.95rem;
}

.radio-label input[type="radio"] {
    accent-color: #1565c0;
}

/* Preview area */
.preview-area {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 0.5rem;
    transition: all 0.2s;
}

.preview-card h4 {
    margin-top: 0;
    margin-bottom: 0.5rem;
}

.preview-card p {
    margin-bottom: 1rem;
}

