.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
}

.preview-theme-dark .btn-primary {
    background: #42a5f5;
}

.preview-theme-system {
    background: #f5f5f5;
    color: #333;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card h4 {
    margin-bottom: 0.25rem;
}

.preview-compact .preview-card p {
    margin-bottom: 0.5rem;
}

