    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    padding: 0.75rem 1.25rem;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    color: #fff;
    z-index: 2000;
    animation: slideIn 0.3s ease;
    box-shadow: 0 3px 12px rgba(0, 0, 0, 0.15);
}

.toast.success {
    background: #2e7d32;
}

.toast.error {
    background: #d32f2f;
}

